import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.hw3Av5Vn.js";const g=JSON.parse('{"title":"Pop","description":"","frontmatter":{},"headers":[],"relativePath":"demos/POP.md","filePath":"demos/POP.md"}'),n={name:"demos/POP.md"};function s(l,e,i,d,h,c){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="pop" tabindex="-1">Pop <a class="header-anchor" href="#pop" aria-label="Permalink to &quot;Pop&quot;">​</a></h1><p>The demo songs in the pop style. Each is described below, with the features it uses; <a href="./../DEMOS">About Demos</a> lists every demo.</p><ul><li><a href="#bless_the_rains">Soft-Rock</a>: <code>bless_the_rains.yml</code></li><li><a href="#chord_progression_generator">Progressions</a>: <code>06_chord_progression_generator.yml</code></li><li><a href="#goodnight_world">Synth-Pop</a>: <code>goodnight_world.yml</code></li><li><a href="#peanut_buttercup">Soul-Pop</a>: <code>peanut_buttercup.yml</code></li><li><a href="#rick_rolling">Dance-Pop</a>: <code>rick_rolling.yml</code></li></ul><p><a id="bless_the_rains"></a></p><h2 id="soft-rock-bless-the-rains-yml" tabindex="-1">Soft-Rock: <code>bless_the_rains.yml</code> <a class="header-anchor" href="#soft-rock-bless-the-rains-yml" aria-label="Permalink to &quot;Soft-Rock: `bless_the_rains.yml`&quot;">​</a></h2><p>An early-eighties soft-rock song in the manner of Africa, with a melody of its own: a marimba riff in sixteenths, congas, a shaker and a cowbell, and a warm pad, the marimba moved through the chords by Progression.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/by_genre/pop/bless_the_rains.yml" target="_blank" rel="noreferrer"><code>examples/by_genre/pop/bless_the_rains.yml</code></a> · A major · 96 BPM · 3:00 · 6 scenes · 8 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">chains</th><th style="text-align:center;">ties</th><th style="text-align:center;">progressions</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr></tbody></table><p><a id="chord_progression_generator"></a></p><h2 id="progressions-06-chord-progression-generator-yml" tabindex="-1">Progressions: <code>06_chord_progression_generator.yml</code> <a class="header-anchor" href="#progressions-06-chord-progression-generator-yml" aria-label="Permalink to &quot;Progressions: `06_chord_progression_generator.yml`&quot;">​</a></h2><p>A pop song in C major made from three patterns one bar long, an arpeggio, a bass figure and a chord pad, each written over chord I and played through a Progression, a different one in every scene: Pop, Fifties, Andalusian in A minor, Pachelbel&#39;s eight chords, Pop again with the pad&#39;s chords inverted so that they move less, and Pop with the pad through a Voice leading generator.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/learning/06_chord_progression_generator.yml" target="_blank" rel="noreferrer"><code>examples/learning/06_chord_progression_generator.yml</code></a> · C major · 96 BPM · 3:00 · 6 scenes · 6 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">chains</th><th style="text-align:center;">ties</th><th style="text-align:center;">key changes</th><th style="text-align:center;">progressions</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr></tbody></table><p><a id="goodnight_world"></a></p><h2 id="synth-pop-goodnight-world-yml" tabindex="-1">Synth-Pop: <code>goodnight_world.yml</code> <a class="header-anchor" href="#synth-pop-goodnight-world-yml" aria-label="Permalink to &quot;Synth-Pop: `goodnight_world.yml`&quot;">​</a></h2><p>An early-eighties synth-pop song in the manner of Sweet Dreams, with a melody of its own: a sixteenth-note synth bass leaping an octave, a cold string pad, a drum machine and a saw lead.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/by_genre/pop/goodnight_world.yml" target="_blank" rel="noreferrer"><code>examples/by_genre/pop/goodnight_world.yml</code></a> · C minor · 126 BPM · 3:03 · 7 scenes · 7 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">chains</th><th style="text-align:center;">ties</th><th style="text-align:center;">progressions</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr></tbody></table><p><a id="peanut_buttercup"></a></p><h2 id="soul-pop-peanut-buttercup-yml" tabindex="-1">Soul-Pop: <code>peanut_buttercup.yml</code> <a class="header-anchor" href="#soul-pop-peanut-buttercup-yml" aria-label="Permalink to &quot;Soul-Pop: `peanut_buttercup.yml`&quot;">​</a></h2><p>A late-sixties soul-pop song in the manner of Build Me Up Buttercup, with a melody of its own: a bouncing piano, horn stabs on the off-beats and a tambourine on two and four, the harmony moved by Progression chains.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/by_genre/pop/peanut_buttercup.yml" target="_blank" rel="noreferrer"><code>examples/by_genre/pop/peanut_buttercup.yml</code></a> · C major · 132 BPM · 3:02 · 8 scenes · 9 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">chains</th><th style="text-align:center;">ties</th><th style="text-align:center;">progressions</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr></tbody></table><p><a id="rick_rolling"></a></p><h2 id="dance-pop-rick-rolling-yml" tabindex="-1">Dance-Pop: <code>rick_rolling.yml</code> <a class="header-anchor" href="#dance-pop-rick-rolling-yml" aria-label="Permalink to &quot;Dance-Pop: `rick_rolling.yml`&quot;">​</a></h2><p>A late-eighties dance-pop song in the manner of Never Gonna Give You Up, with a melody of its own: an octave-bouncing synth bass, off-beat chord stabs and a disco beat. The bass and the stabs are one bar each, moved through the chords by Progression chains.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/by_genre/pop/rick_rolling.yml" target="_blank" rel="noreferrer"><code>examples/by_genre/pop/rick_rolling.yml</code></a> · Bb major · 114 BPM · 2:57 · 7 scenes · 7 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">chains</th><th style="text-align:center;">ties</th><th style="text-align:center;">progressions</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr></tbody></table>',28)])])}const y=t(n,[["render",s]]);export{g as __pageData,y as default};
